function lex(text) {
  const tokens = [];
  let i = 0;
  const specials = '()\'"[{';  // plus '"' 
  while (i < text.length) {
    const c = text[i];
    if (/\s/.test(c)) { i++; continue; }
    if (c === '(') { tokens.push({t:'LP'}); i++; continue; }
    if (c === ')') { tokens.push({t:'RP'}); i++; continue; }
    if (c === '"') { let j = i+1; while (j<text.length && text[j]!=='"') j++; tokens.push({t:'PHRASE', content:text.slice(i+1,j)}); i = j<text.length? j+1 : j; continue; }
    if (c === "'") similar with '
    if (c === '[' || c === '{') { let j=i+1; while(j<text.length && text[j]!==']' && text[j]!=='}') j++; tokens.push({t:'RANGE', content:text.slice(i+1,j), open:c, close: j<text.length? text[j] : ''}); i = j<text.length? j+1: j; continue; }
    // WORD chunk
    let j = i;
    while (j<text.length && !/\s/.test(text[j]) && !'()"\'[{'.includes(text[j])) j++;
    tokens.push({t:'WORD', text:text.slice(i,j)});
    i = j;
  }
}
```

