1	// Query node factories (plain data objects) plus an executor.
2	
3	export function nullQuery() {
4	  return { type: 'null' };
5	}
6	
7	export function term(field, text) {
8	  return { type: 'term', field, text };
9	}
10	
11	export function and(children) {
12	  const kids = children.filter((c) => c.type !== 'null');
13	  if (kids.length === 0) return nullQuery();
14	  if (kids.length === 1) return kids[0];
15	  return { type: 'and', children: kids };
16	}
17	
18	export function or(children) {
19	  const kids = children.filter((c) => c.type !== 'null');
20	  if (kids.length === 0) return nullQuery();
21	  if (kids.length === 1) return kids[0];
22	  return { type: 'or', children: kids };
23	}
24	
25	export function not(child) {
26	  return { type: 'not', child };
27	}
28	
29	export function andMaybe(required, optional) {
30	  return { type: 'andmaybe', required, optional };
31	}
32	
33	export function phrase(field, words) {
34	  return { type: 'phrase', field, words };
35	}
36	
37	export function wildcard(field, pattern) {
38	  return { type: 'wildcard', field, pattern };
39	}
40	
41	export function termRange(field, start, end, startExclusive, endExclusive) {
42	  return { type: 'termrange', field, start, end, startExclusive, endExclusive };
43	}
44	
45	export function every(field) {
46	  return { type: 'every', field };
47	}
48	
49	function wildcardToRegExp(pattern) {
50	  let src = '';
51	  for (const ch of pattern) {
52	    if (ch === '*') src += '.*';
53	    else if (ch === '?') src += '.';
54	    else src += ch.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
55	  }
56	  return new RegExp(`^${src}$`, 'u');
57	}
58	
59	export function execute(query, index) {
60	  switch (query.type) {
61	    case 'null':
62	      return [];
63	
64	    case 'term': {
65	      const postings = index.postings.get(query.field);
66	      const set = postings && postings.get(query.text);
67	      return set ? [...set] : [];
68	    }
69	
70	    case 'and': {
71	      if (query.children.length === 0) return [];
72	      const sets = query.children.map((c) => new Set(execute(c, index)));
73	      sets.sort((a, b) => a.size - b.size);
74	      const [smallest, ...rest] = sets;
75	      return [...smallest].filter((id) => rest.every((s) => s.has(id)));
76	    }
77	
78	    case 'or': {
79	      const result = new Set();
80	      for (const c of query.children) {
81	        for (const id of execute(c, index)) result.add(id);
82	      }
83	      return [...result];
84	    }
85	
86	    case 'not': {
87	      const excluded = new Set(execute(query.child, index));
88	      const result = [];
89	      for (let id = 0; id < index.docCount; id++) {
90	        if (!excluded.has(id)) result.push(id);
91	      }
92	      return result;
93	    }
94	
95	    case 'andmaybe':
96	      return execute(query.required, index);
97	
98	    case 'phrase': {
99	      const words = query.words;
100	      if (words.length === 0) return [];
101	      if (words.length === 1) return execute(term(query.field, words[0]), index);
102	      const result = [];
103	      for (const [docId, tokens] of index.docTokens) {
104	        const fieldTokens = tokens.get(query.field) || [];
105	        outer: for (let i = 0; i + words.length <= fieldTokens.length; i++) {
106	          for (let j = 0; j < words.length; j++) {
107	            if (fieldTokens[i + j] !== words[j]) continue outer;
108	          }
109	          result.push(docId);
110	          break;
111	        }
112	      }
113	      return result;
114	    }
115	
116	    case 'wildcard': {
117	      const re = wildcardToRegExp(query.pattern);
118	      const postings = index.postings.get(query.field);
119	      if (!postings) return [];
120	      const result = new Set();
121	      for (const [t, docIds] of postings) {
122	        if (re.test(t)) {
123	          for (const id of docIds) result.add(id);
124	        }
125	      }
126	      return [...result];
127	    }
128	
129	    case 'termrange': {
130	      const { start, end, startExclusive, endExclusive } = query;
131	      const postings = index.postings.get(query.field);
132	      if (!postings) return [];
133	      const result = new Set();
134	      for (const [t, docIds] of postings) {
135	        const aboveStart =
136	          start === null || t > start || (!startExclusive && t === start);
137	        const belowEnd =
138	          end === null || t < end || (!endExclusive && t === end);
139	        if (aboveStart && belowEnd) {
140	          for (const id of docIds) result.add(id);
141	        }
142	      }
143	      return [...result];
144	    }
145	
146	    case 'every': {
147	      const result = [];
148	      for (const [docId, tokens] of index.docTokens) {
149	        const fieldTokens = tokens.get(query.field);
150	        if (fieldTokens && fieldTokens.length >= 1) result.push(docId);
151	      }
152	      return result;
153	    }
154	
155	    default:
156	      throw new Error(`Unknown query type: ${query.type}`);
157	  }
158	}

1	// Replicates whoosh's StandardAnalyzer: StandardTokenizer + LowercaseFilter + StopFilter.
2	
3	export const STOP_WORDS = new Set([
4	  'a','an','and','are','as','at','be','by','can','for','from','have','if','in',
5	  'is','it','may','not','of','on','or','tbd','that','the','this','to','us','we',
6	  'when','will','with','yet','you','your'
7	]);
8	
9	const TOKEN_RE = /[\p{L}\p{N}_]+(\.?[\p{L}\p{N}_]+)*/gu;
10	
11	export function analyze(text) {
12	  const tokens = [];
13	  for (const match of String(text).matchAll(TOKEN_RE)) {
14	    const tok = match[0];
15	    if ([...tok].length < 2) continue;
16	    const lower = tok.toLowerCase();
17	    if (STOP_WORDS.has(lower)) continue;
18	    tokens.push(lower);
19	  }
20	  return tokens;
21	}
